import {featuresAtLevel,changes} from './sid-model.mjs';
import {distanceFromFirst} from './sid-longitudinal-model.mjs';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={sgb:'Species-level bins',genus:'Genus groups',family:'Family groups'},colors={sgb:'#a5683f',genus:'#176e60',family:'#788d39',phylo:'#7868a5'},short=d=>new Date(d+'T12:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'UTC'});
export function childFeatures(data,parent,level){if(!parent||level==='sgb')return [];const ids=new Set(parent.sgbs),indices=data.features.flatMap((f,i)=>ids.has(f.metaphlan_id)?[i]:[]),subset={features:indices.map(i=>data.features[i]),samples:data.samples.map(s=>({...s,shares:indices.map(i=>s.shares[i])}))};return featuresAtLevel(subset,level==='family'?'genus':'sgb');}
export function renderScale({data,phylogeny,start,end,level,selected,onSelect}){
 const series=['sgb','genus','family'].map(rank=>({id:rank,name:names[rank],values:distanceFromFirst(featuresAtLevel(data,rank),data.samples).map(s=>s.brayCurtis)}));
 series.push({id:'phylo',name:'Weighted UniFrac',values:phylogeny.matrix[0]});
 const l=50,r=900,top=22,bottom=230,x=d=>l+(Date.parse(d)-Date.parse(data.samples[0].date))/(Date.parse(data.samples.at(-1).date)-Date.parse(data.samples[0].date))*(r-l),y=v=>bottom-v*(bottom-top);
 let svg='<svg viewBox="0 0 960 300" role="img" aria-label="Distance from the first observed stool sample, comparing species, genus, family and phylogeny-aware metrics">';
 for(let v=0;v<=1;v+=.25){svg+=`<line x1="${l}" x2="${r}" y1="${y(v)}" y2="${y(v)}" stroke="#dce3db"/><text x="${l-8}" y="${y(v)+4}" text-anchor="end" font-size="12">${Math.round(v*100)}%</text>`}
 for(const s of series){svg+=`<polyline points="${s.values.map((v,i)=>`${x(data.samples[i].date)},${y(v)}`).join(' ')}" fill="none" stroke="${colors[s.id]}" stroke-width="${s.id===level?3:2}" ${s.id==='phylo'?'stroke-dasharray="6 4"':''}/>`;s.values.forEach((v,i)=>{svg+=`<circle cx="${x(data.samples[i].date)}" cy="${y(v)}" r="4" fill="${colors[s.id]}"><title>${s.name}, ${data.samples[i].date}: ${(v*100).toFixed(2)}%</title></circle>`})}
 data.samples.forEach((s,i)=>svg+=`<text x="${x(s.date)}" y="${i===3?278:256}" text-anchor="middle" font-size="12">${short(s.date)}${i===2?' *':i>2?' †':''}</text>`);$('referencePlot').innerHTML=svg+'</svg>';
 $('referenceLegend').innerHTML=series.map(s=>`<span style="color:${colors[s.id]}">● ${s.name}${s.id!=='phylo'?' · Bray–Curtis':''}</span>`).join('');
 $('referenceTable').innerHTML='<table><thead><tr><th>Reported date</th>'+series.map(s=>`<th>${s.name}</th>`).join('')+'</tr></thead><tbody>'+data.samples.map((s,i)=>`<tr><td>${s.date}${i===2?' *':i>2?' †':''}</td>${series.map(v=>`<td>${(v.values[i]*100).toFixed(1)}%</td>`).join('')}</tr>`).join('')+'</tbody></table>';
 const ranks=['sgb','genus','family'].map(rank=>({rank,name:names[rank],distance:featuresAtLevel(data,rank).reduce((v,f)=>v+Math.abs(f.values[end]-f.values[start]),0)/2}));
 $('scaleInterval').textContent=`Selected interval: ${data.samples[start].date} → ${data.samples[end].date}. All features are included, regardless of display filters.`;
 $('scaleCards').innerHTML=[...ranks,{rank:'phylo',name:'Weighted UniFrac',distance:phylogeny.matrix[start][end]}].map(v=>`<div class="scale-card"><span>${v.name}</span><b style="color:${colors[v.rank]}">${(v.distance*100).toFixed(1)}%</b><small>${v.rank==='phylo'?'Normalized branch-weighted distance':'Bray–Curtis dissimilarity'}</small></div>`).join('');
 $('treeCoverage').textContent=`Reference tree: ${phylogeny.database}. ${phylogeny.mappedFeatures}/${phylogeny.totalFeatures} SGBs mapped; 100% of supplied abundance retained in every visit. Reference root and branch lengths preserved.`;
 const children=childFeatures(data,selected,level);$('memberPanel').hidden=!children.length;
 if(children.length){const childLevel=level==='family'?'genus':'sgb',rows=changes(children,start,end);$('memberTitle').textContent=`Inside ${selected.name}: ${childLevel==='genus'?'genus':'SGB'} changes`;$('memberRows').innerHTML=rows.map(f=>`<tr><td><button data-child="${esc(f.id)}">${esc(f.name)}</button></td><td>${(f.start*100).toFixed(3)}</td><td>${(f.end*100).toFixed(3)}</td><td>${f.delta>0?'+':''}${f.delta.toFixed(3)}</td></tr>`).join('');$('memberRows').onclick=e=>{const b=e.target.closest('[data-child]');if(b)onSelect(childLevel,b.dataset.child)};
 const positive=rows.filter(r=>r.delta>0).reduce((s,r)=>s+r.delta,0),negative=rows.filter(r=>r.delta<0).reduce((s,r)=>s+r.delta,0);$('memberSummary').textContent=`Member increases total +${positive.toFixed(3)} pp; decreases total ${negative.toFixed(3)} pp; net ${(positive+negative).toFixed(3)} pp. Opposing changes can cancel at the parent level. These are whole-sample shares, not percentages renormalized within this group. Selecting a member clears feature filters.`;}
}
